from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
import os

app = FastAPI()
port = int(os.getenv('PORT', 3000))

API_KEY = 'my-secret-key'

def api_key_middleware(request: Request):
    api_key = request.headers.get('x-api-key')
    if not api_key or api_key != API_KEY:
        return JSONResponse(status_code=401, content={'error': 'Unauthorized'})
    return None

@app.get('/public')
def public():
    return {'message': 'Welcome to the public endpoint!'}

@app.get('/protected')
def protected(request: Request):
    err = api_key_middleware(request)
    if err:
        return err
    return {'message': 'Welcome to the protected endpoint!', 'data': 'sensitive data'}

@app.get('/admin')
def admin(request: Request):
    err = api_key_middleware(request)
    if err:
        return err
    return {'message': 'Admin panel', 'data': 'admin data'}

